import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        opp_last = history[-1][1]
        return 'C' if opp_last == 'C' else 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_def = 0
    my_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    for a in my:
        if a == 'D':
            my_def += 1

    opp_last = opp[-1]
    my_last = my[-1]

    # Detect opponent cooperation rate
    opp_coop_rate = (n - opp_def) / float(n)

    # Endgame: squeeze last few rounds
    remaining = 100 - n
    if remaining <= 1:
        return 'D'

    # If opponent never defects, exploit heavily but leave room for cooperation
    if opp_def == 0:
        # Exploit aggressively against naive cooperators, but keep some C
        # to avoid being punished by forgiving retaliators late.
        if n < 3:
            return 'C'
        if remaining <= 3:
            return 'D'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Compute recent defection stats
    recent_len = 8 if n >= 8 else n
    recent_opp_def = 0
    for i in range(n - recent_len, n):
        if opp[i] == 'D':
            recent_opp_def += 1

    # Detect opponent defection streaks
    opp_d_streak = 0
    for a in reversed(opp):
        if a == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for a in reversed(my):
        if a == 'D':
            my_d_streak += 1
        else:
            break

    # Hardcore defectors: defect back
    if opp_d_streak >= 3:
        # Occasionally test cooperation to recover mutual gain
        if remaining > 5 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Strong retaliation to double defection
    if opp_d_streak == 2:
        if my_last == 'D' and rng.random() < 0.15 and remaining > 3:
            return 'C'
        return 'D'

    # Single defection by opponent
    if opp_last == 'D':
        # If we defected last (we already punished), return to cooperation
        if my_last == 'D':
            # But if opponent is generally defective, stay aggressive
            if opp_coop_rate < 0.4:
                return 'D'
            if rng.random() < 0.85:
                return 'C'
            return 'D'
        # We cooperated and got defected: retaliate
        return 'D'

    # Opponent cooperated last
    # If opponent is generally cooperative, cooperate most of the time
    if opp_coop_rate > 0.85 and recent_opp_def == 0:
        # Tit-for-tat-ish, with rare exploitation
        if my_d_streak >= 1:
            # We defected recently; offer cooperation to restore
            return 'C'
        if rng.random() < 0.04 and remaining > 4:
            return 'D'
        return 'C'

    if opp_coop_rate > 0.6:
        # Moderately cooperative: cooperate but retaliate on any D
        if my_d_streak >= 2:
            return 'C'
        if rng.random() < 0.03 and remaining > 4:
            return 'D'
        return 'C'

    if opp_coop_rate > 0.35:
        # Mixed opponent: probe with occasional D, cooperate otherwise
        if recent_opp_def >= 3:
            return 'D'
        if rng.random() < 0.15 and remaining > 4:
            return 'D'
        return 'C'

    # Hostile opponent: mostly defect, occasional C probe
    if rng.random() < 0.08 and remaining > 4:
        return 'C'
    return 'D'
